-- arc SJ (#1359) fixture: one statement per line, run verbatim by wadjet and PostgreSQL 17.11.
-- Preserved sides sj_p_<shape>; empty side sj_e (no rows); sj_f is filtered or limited to empty.
CREATE TABLE sj_p_one AS SELECT CAST(x AS INTEGER) AS id, CAST(x AS INTEGER) AS k_int, CAST(CAST(x AS INTEGER) AS BIGINT) + 10000000000 AS k_big, 'k' || CAST(CAST(x AS INTEGER) AS VARCHAR) AS k_txt, DATE '2000-01-01' + CAST(x AS INTEGER) AS k_date, CAST(x * 1.25 AS NUMERIC(12,2)) AS v_dec, ARRAY[CAST(x AS INTEGER), CAST(x AS INTEGER) + 1] AS v_arr FROM generate_series(1, 1) AS s(x)
CREATE TABLE sj_p_b2048 AS SELECT CAST(x AS INTEGER) AS id, CAST(x AS INTEGER) AS k_int, CAST(CAST(x AS INTEGER) AS BIGINT) + 10000000000 AS k_big, 'k' || CAST(CAST(x AS INTEGER) AS VARCHAR) AS k_txt, DATE '2000-01-01' + CAST(x AS INTEGER) AS k_date, CAST(x * 1.25 AS NUMERIC(12,2)) AS v_dec, ARRAY[CAST(x AS INTEGER), CAST(x AS INTEGER) + 1] AS v_arr FROM generate_series(1, 1000) AS s(x)
CREATE TABLE sj_p_b20000 AS SELECT CAST(x AS INTEGER) AS id, CAST(x AS INTEGER) AS k_int, CAST(CAST(x AS INTEGER) AS BIGINT) + 10000000000 AS k_big, 'k' || CAST(CAST(x AS INTEGER) AS VARCHAR) AS k_txt, DATE '2000-01-01' + CAST(x AS INTEGER) AS k_date, CAST(x * 1.25 AS NUMERIC(12,2)) AS v_dec, ARRAY[CAST(x AS INTEGER), CAST(x AS INTEGER) + 1] AS v_arr FROM generate_series(1, 1000) AS s(x)
CREATE TABLE sj_p_nullk AS SELECT CAST(x AS INTEGER) AS id, CASE WHEN x % 3 = 0 THEN NULL ELSE CAST(x AS INTEGER) END AS k_int, CAST(CASE WHEN x % 3 = 0 THEN NULL ELSE CAST(x AS INTEGER) END AS BIGINT) + 10000000000 AS k_big, 'k' || CAST(CASE WHEN x % 3 = 0 THEN NULL ELSE CAST(x AS INTEGER) END AS VARCHAR) AS k_txt, DATE '2000-01-01' + CASE WHEN x % 3 = 0 THEN NULL ELSE CAST(x AS INTEGER) END AS k_date, CAST(x * 1.25 AS NUMERIC(12,2)) AS v_dec, ARRAY[CAST(x AS INTEGER), CAST(x AS INTEGER) + 1] AS v_arr FROM generate_series(1, 300) AS s(x)
CREATE TABLE sj_p_dup AS SELECT CAST(x AS INTEGER) AS id, CAST(x % 50 AS INTEGER) AS k_int, CAST(CAST(x % 50 AS INTEGER) AS BIGINT) + 10000000000 AS k_big, 'k' || CAST(CAST(x % 50 AS INTEGER) AS VARCHAR) AS k_txt, DATE '2000-01-01' + CAST(x % 50 AS INTEGER) AS k_date, CAST(x * 1.25 AS NUMERIC(12,2)) AS v_dec, ARRAY[CAST(x AS INTEGER), CAST(x AS INTEGER) + 1] AS v_arr FROM generate_series(1, 1000) AS s(x)
CREATE TABLE sj_e (k_int INTEGER, k_big BIGINT, k_txt VARCHAR, k_date DATE, ey INTEGER)
CREATE TABLE sj_f AS SELECT CAST(-x AS INTEGER) AS k_int, CAST(-x AS BIGINT) AS k_big, 'f' || CAST(x AS VARCHAR) AS k_txt, DATE '1990-01-01' + CAST(x AS INTEGER) AS k_date, CAST(x AS INTEGER) AS ey FROM generate_series(1, 50) AS s(x)
